for command in awk bash chmod chown cmp curl dirname docker env find grep head id install \
  mkdir mv python3 realpath sed seq sha256sum sleep sort ss stat sync tail timeout tr visudo wc; do
  command -v "$command" >/dev/null 2>&1 || die "required command is unavailable: $command"
done

emit_exact_nofollow_file() {
  local path="$1" expected_dev_ino="$2" expected_size="$3" expected_sha="$4" expected_mode="${5:-0600}"
  env -i PATH="$SAFE_PATH" python3 -I /dev/fd/3 "$path" "$expected_dev_ino" "$expected_size" "$expected_sha" "$expected_mode" 3<<'PY'
import hashlib, os, stat, sys
path, expected_dev_ino, expected_size, expected_sha, expected_mode = sys.argv[1:]
try:
    if os.path.islink(path) or not os.path.isfile(path) or os.path.realpath(path) != path:
        raise RuntimeError()
    fd = os.open(path, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW)
    try:
        before = os.fstat(fd)
        data = bytearray()
        while True:
            chunk = os.read(fd, 1024 * 1024)
            if not chunk: break
            data.extend(chunk)
        after = os.fstat(fd)
        exact = (before.st_dev, before.st_ino, before.st_uid, before.st_gid, stat.S_IMODE(before.st_mode),
                 before.st_nlink, before.st_size)
        if before != after or exact != (int(expected_dev_ino.split(':')[0]), int(expected_dev_ino.split(':')[1]),
                                        0, 0, int(expected_mode, 8), 1, int(expected_size)):
            raise RuntimeError()
        if hashlib.sha256(data).hexdigest() != expected_sha:
            raise RuntimeError()
        os.write(1, data)
    finally:
        os.close(fd)
except Exception:
    raise SystemExit(1)
PY
}

verify_exact_nofollow_file_digest() {
  local path="$1" expected_dev_ino="$2" expected_size="$3" expected_sha="$4" expected_mode="${5:-0400}"
  timeout 65s env -i PATH="$SAFE_PATH" python3 -I /dev/fd/3 \
    "$path" "$expected_dev_ino" "$expected_size" "$expected_sha" "$expected_mode" 3<<'PY'
import hashlib
import os
import signal
import stat
import sys

path, expected_dev_ino, expected_size_text, expected_sha, expected_mode = sys.argv[1:]
try:
    expected_size = int(expected_size_text)
    expected_device, expected_inode = (int(value) for value in expected_dev_ino.split(':', 1))
    if (
        expected_size < 1
        or expected_size > 1024 * 1024 * 1024
        or len(expected_sha) != 64
        or any(value not in '0123456789abcdef' for value in expected_sha)
        or os.path.islink(path)
        or not os.path.isfile(path)
        or os.path.realpath(path) != path
    ):
        raise RuntimeError()
    signal.alarm(60)
    descriptor = os.open(path, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW)
    try:
        before = os.fstat(descriptor)
        named_before = os.lstat(path)
        exact = (
            before.st_dev, before.st_ino, before.st_uid, before.st_gid,
            stat.S_IMODE(before.st_mode), before.st_nlink, before.st_size,
        )
        if (
            not stat.S_ISREG(before.st_mode)
            or (before.st_dev, before.st_ino) != (named_before.st_dev, named_before.st_ino)
            or exact != (
                expected_device, expected_inode, 0, 0, int(expected_mode, 8), 1, expected_size,
            )
        ):
            raise RuntimeError()
        digest = hashlib.sha256()
        total = 0
        while True:
            chunk = os.read(descriptor, 1024 * 1024)
            if not chunk:
                break
            total += len(chunk)
            if total > expected_size:
                raise RuntimeError()
            digest.update(chunk)
        after = os.fstat(descriptor)
        named_after = os.lstat(path)
        before_contract = (
            before.st_dev, before.st_ino, before.st_mode, before.st_uid, before.st_gid,
            before.st_nlink, before.st_size, before.st_mtime_ns, before.st_ctime_ns,
        )
        after_contract = (
            after.st_dev, after.st_ino, after.st_mode, after.st_uid, after.st_gid,
            after.st_nlink, after.st_size, after.st_mtime_ns, after.st_ctime_ns,
        )
        if (
            total != expected_size
            or digest.hexdigest() != expected_sha
            or before_contract != after_contract
            or (after.st_dev, after.st_ino) != (named_after.st_dev, named_after.st_ino)
            or os.path.realpath(path) != path
        ):
            raise RuntimeError()
    finally:
        os.close(descriptor)
except Exception:
    raise SystemExit(1)
PY
}

derive_customer_web_archive_identities() {
  local archive_path="$1" validator_path="$2" image_tag="$3" config_id="$4" release="$5"
  env -i PATH="$SAFE_PATH" python3 -I "$validator_path" \
    "$archive_path" "$image_tag" "$config_id" oci 10 28 || return 1
  env -i PATH="$SAFE_PATH" python3 -I /dev/fd/3 \
    "$archive_path" "$image_tag" "$config_id" "$release" 3<<'PY'
import hashlib
import json
import re
import sys
import tarfile

archive_path, expected_tag, expected_config_id, expected_release = sys.argv[1:]

try:
    if not re.fullmatch(r'sha256:[0-9a-f]{64}', expected_config_id):
        raise RuntimeError()
    with tarfile.open(archive_path, mode='r:') as archive:
        index = json.load(archive.extractfile('index.json'))
        if not isinstance(index, dict) or set(index) != {'schemaVersion', 'mediaType', 'manifests'}:
            raise RuntimeError()
        if index['schemaVersion'] != 2 or index['mediaType'] != 'application/vnd.oci.image.index.v1+json':
            raise RuntimeError()
        descriptors = index['manifests']
        if not isinstance(descriptors, list) or len(descriptors) != 1:
            raise RuntimeError()
        descriptor = descriptors[0]
        if not isinstance(descriptor, dict) or set(descriptor) != {'mediaType', 'digest', 'size', 'annotations'}:
            raise RuntimeError()
        runtime_id = descriptor['digest']
        if not re.fullmatch(r'sha256:[0-9a-f]{64}', runtime_id):
            raise RuntimeError()
        if descriptor != {
            'mediaType': 'application/vnd.oci.image.manifest.v1+json',
            'digest': runtime_id,
            'size': descriptor['size'],
            'annotations': {
                'io.containerd.image.name': f'docker.io/library/{expected_tag}',
                'org.opencontainers.image.ref.name': expected_tag.rsplit(':', 1)[1],
            },
        } or isinstance(descriptor['size'], bool) or not isinstance(descriptor['size'], int) or descriptor['size'] <= 0:
            raise RuntimeError()
        manifest_stream = archive.extractfile(f"blobs/sha256/{runtime_id.removeprefix('sha256:')}")
        if manifest_stream is None:
            raise RuntimeError()
        manifest_bytes = manifest_stream.read()
        if len(manifest_bytes) != descriptor['size'] or hashlib.sha256(manifest_bytes).hexdigest() != runtime_id.removeprefix('sha256:'):
            raise RuntimeError()
        manifest = json.loads(manifest_bytes)
        config_descriptor = manifest.get('config')
        if not isinstance(config_descriptor, dict) or config_descriptor.get('digest') != expected_config_id:
            raise RuntimeError()
        if config_descriptor.get('mediaType') != 'application/vnd.oci.image.config.v1+json':
            raise RuntimeError()
        config_stream = archive.extractfile(f"blobs/sha256/{expected_config_id.removeprefix('sha256:')}")
        if config_stream is None:
            raise RuntimeError()
        config_bytes = config_stream.read()
        if len(config_bytes) != config_descriptor.get('size') or hashlib.sha256(config_bytes).hexdigest() != expected_config_id.removeprefix('sha256:'):
            raise RuntimeError()
        config = json.loads(config_bytes)
        image_config = config.get('config')
        if config.get('architecture') != 'amd64' or config.get('os') != 'linux' or not isinstance(image_config, dict):
            raise RuntimeError()
        if image_config.get('User') != '10001:10001' or image_config.get('Cmd') != ['node', 'apps/customer-web/dist/index.js']:
            raise RuntimeError()
        if image_config.get('Entrypoint') != ['docker-entrypoint.sh'] or image_config.get('WorkingDir') != '/workspace':
            raise RuntimeError()
        labels = image_config.get('Labels') or {}
        if labels.get('org.opencontainers.image.revision') != expected_release or labels.get('org.opencontainers.image.title') != 'fetanagent-customer-web':
            raise RuntimeError()
    print(expected_config_id)
    print(runtime_id)
except Exception:
    raise SystemExit(1)
PY
}

