require_owner_contract() {
  local container_id="$1" expected_release="$2" expected_image_id="$3"
  docker_local container inspect "$container_id" |
    env -i PATH="$SAFE_PATH" python3 -I /dev/fd/3 \
      "$container_id" "$expected_release" "$expected_image_id" "$PROJECT_NAME" "$CONTROL_VOLUME" \
      "$OWNER_NETWORK" "$OWNER_RECEIPT_ROOT" "$SECRET_ROOT" 3<<'PY'
import json
import sys

container_id, release, expected_image_id, project, control_volume, network, receipt_root, secret_root = sys.argv[1:]
try:
    payload = json.load(sys.stdin)
    if not isinstance(payload, list) or len(payload) != 1:
        raise RuntimeError()
    value = payload[0]
    config = value['Config']
    host = value['HostConfig']
    labels = config['Labels']
    if (
        value['Id'] != container_id
        or labels.get('com.docker.compose.project') != project
        or labels.get('com.docker.compose.service') != 'owner-control'
        or labels.get('org.opencontainers.image.revision') != release
        or (expected_image_id != '-' and value['Image'] != expected_image_id)
        or config['User'] != '10001:10001'
        or config['Cmd'] != ['node', 'apps/admin/dist/index.js']
        or host['ReadonlyRootfs'] is not True
        or host['Privileged'] is not False
        or host.get('Init') is not True
        or host.get('PidMode', '') != ''
        or host['NetworkMode'] != network
        or host['RestartPolicy'].get('Name') != 'no'
        or host.get('AutoRemove') is not False
        or host.get('CapAdd') is not None
        or host.get('CapDrop') != ['ALL']
        or host.get('SecurityOpt') != ['no-new-privileges:true']
        or host.get('PidsLimit') != 128
        or host.get('Memory') != 268435456
        or host.get('NanoCpus') != 500000000
        or host.get('PortBindings') != {'3002/tcp': [{'HostIp': '127.0.0.1', 'HostPort': '3002'}]}
        or host.get('RestartPolicy') != {'Name': 'no', 'MaximumRetryCount': 0}
        or config.get('StopTimeout') != 15
    ):
        raise RuntimeError()
    environments = config['Env']
    if (
        environments.count('FINANCIAL_ACTIONS_MODE=dry_run') != 1
        or 'KEMERBET_EXECUTOR_ENABLED=false' not in environments
        or 'KEMERBET_FINAL_ACTION_ENABLED=false' not in environments
        or 'INTERNAL_OWNER_CONTROL_RUNTIME_ENABLED=true' not in environments
        or 'TELEGRAM_BOT_ENABLED=false' not in environments
        or 'INTERNAL_TELEGRAM_INGRESS_ENABLED=false' not in environments
    ):
        raise RuntimeError()
    expected_mounts = {
        '/run/fetanagent-kemerbet-session-control': ('volume', control_volume, True),
        '/run/fetanagent-kemerbet-readiness-cohort-receipts': ('bind', receipt_root, False),
        '/run/secrets/owner_control_database_url': ('bind', f'{secret_root}/owner-database-url', False),
        '/run/secrets/owner_control_supabase_publishable_key': ('bind', f'{secret_root}/publishable-key', False),
        '/run/secrets/owner_receiver_reference_encryption_master': ('bind', f'{secret_root}/deposit-proof-reference-encryption-master', False),
        '/run/secrets/owner_receiver_reference_fingerprint_master': ('bind', f'{secret_root}/deposit-proof-reference-fingerprint-master', False),
        '/run/configs/supabase_ca_certificate': ('bind', f'{secret_root}/supabase-ca.crt', False),
        '/etc/fetanagent/deposit-proof-reference-profile.v2.json': ('bind', f'{secret_root}/deposit-proof-reference-profile.v2.json', False),
    }
    expected_tmpfs = {'/tmp': 'rw,noexec,nosuid,size=32m,mode=1777'}
    if host.get('Tmpfs') != expected_tmpfs:
        raise RuntimeError()
    observed = {}
    for mount in value['Mounts']:
        destination = mount['Destination']
        if destination in observed:
            raise RuntimeError()
        source = mount.get('Name') if mount['Type'] == 'volume' else mount.get('Source', '')
        observed[destination] = (mount['Type'], source, mount['RW'])
    if observed != expected_mounts:
        raise RuntimeError()
    networks = value['NetworkSettings']['Networks']
    if set(networks) != {network}:
        raise RuntimeError()
    ports = value['NetworkSettings']['Ports']
    if value['State']['Running'] and ports != {'3002/tcp': [{'HostIp': '127.0.0.1', 'HostPort': '3002'}]}:
        raise RuntimeError()
except Exception:
    raise SystemExit(1)
PY
}

require_owner_image_contract() {
  local container_id container_image image_descriptor image_id
  [[ "$(docker_local version --format '{{.Server.Version}}|{{.Server.APIVersion}}|{{.Server.Os}}|{{.Server.Arch}}')" == \
      '29.6.0|1.55|linux|amd64' &&
    "$(docker_local info --format '{{.Driver}}|{{json .DriverStatus}}|{{json .Warnings}}')" == \
      'overlayfs|[["driver-type","io.containerd.snapshotter.v1"]]|null' ]] || return 1
  while IFS= read -r container_id; do
    [[ -n "$container_id" ]] || continue
    container_image="$(docker_local container inspect "$container_id" --format '{{.Image}}')" || return 1
    image_id="$(docker_local image inspect "$container_image" --format '{{.Id}}')" || return 1
    image_descriptor="$(docker_local image inspect "$container_image" --format '{{.Descriptor.digest}}')" || return 1
    [[ "$container_image" == "$image_id" && "$image_id" == "$image_descriptor" ]] || return 1
  done < <(docker_local container ls --all --quiet)
  docker_local image inspect "$OWNER_IMAGE" |
    env -i PATH="$SAFE_PATH" python3 -I /dev/fd/3 \
      "$CLAIM_ROOT/$IMAGE_ARCHIVE_NAME" "$SOURCE_OWNER_LOADED_IMAGE_ID" "$SOURCE_OWNER_IMAGE_ID" "$OWNER_IMAGE" "$CANONICAL_H14" 3<<'PY'
import json
import sys
import tarfile

archive_path, expected_image_id, expected_config_id, expected_tag, expected_revision = sys.argv[1:]
expected_digest = expected_image_id.removeprefix('sha256:')
expected_config_digest = expected_config_id.removeprefix('sha256:')
try:
    observed = json.load(sys.stdin)
    if not isinstance(observed, list) or len(observed) != 1:
        raise RuntimeError()
    image = observed[0]
    with tarfile.open(archive_path, 'r:*') as archive:
        index = json.load(archive.extractfile('index.json'))
        descriptor = index['manifests'][0]
        manifest = json.load(archive.extractfile(f"blobs/sha256/{expected_digest}"))
        config = json.load(archive.extractfile(f"blobs/sha256/{expected_config_digest}"))
    if descriptor != image.get('Descriptor'):
        raise RuntimeError()
    if descriptor != {
        'mediaType': 'application/vnd.oci.image.manifest.v1+json',
        'digest': f'sha256:{expected_digest}',
        'size': 1924,
        'annotations': {
            'io.containerd.image.name': 'docker.io/library/fetanagent-owner-control:06459511d933',
            'org.opencontainers.image.ref.name': '06459511d933',
        },
    }:
        raise RuntimeError()
    if set(config) != {'architecture', 'config', 'created', 'history', 'os', 'rootfs'}:
        raise RuntimeError()
    if config['architecture'] != 'amd64' or config['os'] != 'linux' or config.get('variant') is not None:
        raise RuntimeError()
    if image.get('Architecture') != config['architecture'] or image.get('Os') != config['os'] or image.get('Variant'):
        raise RuntimeError()
    if image.get('Id') != expected_image_id:
        raise RuntimeError()
    if image.get('RepoTags') != [expected_tag]:
        raise RuntimeError()
    if image.get('RepoDigests') != [f'fetanagent-owner-control@sha256:{expected_digest}']:
        raise RuntimeError()
    if set(config['config']) != {'ArgsEscaped', 'Cmd', 'Entrypoint', 'Env', 'Healthcheck', 'Labels', 'User', 'WorkingDir'}:
        raise RuntimeError()
    if image.get('Config') != config['config']:
        raise RuntimeError()
    if config['config']['User'] != '10001:10001' or config['config']['Cmd'] != ['node', 'apps/admin/dist/index.js']:
        raise RuntimeError()
    if config['config']['Labels'].get('org.opencontainers.image.revision') != expected_revision:
        raise RuntimeError()
    layers = [entry['digest'] for entry in manifest['layers']]
    if config['rootfs'] != {'type': 'layers', 'diff_ids': layers} or len(layers) != 11:
        raise RuntimeError()
    if image.get('RootFS') != {'Type': 'layers', 'Layers': layers}:
        raise RuntimeError()
    history = config['history']
    if len(history) != 23 or sum(not item.get('empty_layer', False) for item in history) != 11:
        raise RuntimeError()
except Exception:
    raise SystemExit(1)
PY
}

require_customer_web_runtime_image_contract() {
  local archive_path="$1" config_id="$2" runtime_id="$3" image_tag="$4" release="$5"
  docker_local image inspect "$image_tag" |
    env -i PATH="$SAFE_PATH" python3 -I /dev/fd/3 \
      "$archive_path" "$config_id" "$runtime_id" "$image_tag" "$release" 3<<'PY'
import hashlib
import json
import re
import sys
import tarfile

archive_path, expected_config_id, expected_runtime_id, expected_tag, expected_release = sys.argv[1:]

try:
    observed = json.load(sys.stdin)
    if not isinstance(observed, list) or len(observed) != 1:
        raise RuntimeError()
    image = observed[0]
    with tarfile.open(archive_path, mode='r:') as archive:
        index = json.load(archive.extractfile('index.json'))
        descriptor = index['manifests'][0]
        if descriptor.get('digest') != expected_runtime_id:
            raise RuntimeError()
