require_loaded_image_unused() {
  [[ -z "$(docker_local container ls --all --quiet --filter "ancestor=$OWNER_IMAGE")" ]]
}

require_loaded_image_used_only_by() {
  local expected_id="$1" inventory
  [[ "$expected_id" =~ ^[0-9a-f]{64}$ ]] || return 1
  inventory="$(docker_local container ls --all --quiet --no-trunc --filter "ancestor=$OWNER_IMAGE")" || return 1
  [[ "$inventory" == "$expected_id" ]]
}

capture_complete_docker_create_inventory() {
  local image_ids network_ids volume_names volume holders
  image_ids="$(docker_local image ls --all --quiet --no-trunc | LC_ALL=C sort -u)" || return 1
  network_ids="$(docker_local network ls --quiet --no-trunc | LC_ALL=C sort -u)" || return 1
  volume_names="$(docker_local volume ls --quiet | LC_ALL=C sort -u)" || return 1
  {
    [[ -z "$image_ids" ]] || docker_local image inspect $image_ids
    printf '\n__FETANAGENT_NETWORKS__\n'
    [[ -z "$network_ids" ]] || docker_local network inspect $network_ids
    printf '\n__FETANAGENT_VOLUMES__\n'
    [[ -z "$volume_names" ]] || docker_local volume inspect $volume_names
    printf '\n__FETANAGENT_HOLDERS__\n'
    while IFS= read -r volume; do
      [[ -n "$volume" ]] || continue
      holders="$(container_full_ids_for_volume "$volume")" || return 1
      printf '%s\t%s\n' "$volume" "${holders//$'\n'/,}"
    done <<<"$volume_names"
  } | env -i PATH="$SAFE_PATH" python3 -I /dev/fd/3 3<<'PY'
import json, sys
raw=sys.stdin.read()
images, rest=raw.split('\n__FETANAGENT_NETWORKS__\n',1)
networks, rest=rest.split('\n__FETANAGENT_VOLUMES__\n',1)
volumes, holders=rest.split('\n__FETANAGENT_HOLDERS__\n',1)
def payload(value):
    value=value.strip()
    return [] if not value else json.loads(value)
volume_payload=payload(volumes)
volume_names={item.get('Name') for item in volume_payload}
if None in volume_names or len(volume_names)!=len(volume_payload): raise SystemExit(1)
holder_map={}
for line in holders.splitlines():
    if not line: continue
    if line.count('\t') != 1: raise SystemExit(1)
    name, ids=line.split('\t',1)
    if not name or name in holder_map: raise SystemExit(1)
    values=[] if ids=='' else ids.split(',')
    if any(not __import__('re').fullmatch(r'[0-9a-f]{64}', value) for value in values): raise SystemExit(1)
    if values != sorted(set(values)): raise SystemExit(1)
    holder_map[name]=values
if set(holder_map) != volume_names: raise SystemExit(1)
result={'images':payload(images),'networks':payload(networks),'volumes':volume_payload,'holders':holder_map}
print(json.dumps(result,sort_keys=True,separators=(',',':')))
PY
}

require_exact_owner_inventory_delta_phase() {
  local before="$1" after="$2" new_owner="$3" phase="$4"
  printf '%s\n__FETANAGENT_AFTER__\n%s\n' "$before" "$after" |
    env -i PATH="$SAFE_PATH" python3 -I /dev/fd/3 "$new_owner" "$OWNER_NETWORK" "$PROFILE_VOLUME" "$CONTROL_VOLUME" "$phase" 3<<'PY'
import copy, ipaddress, json, re, sys
new_owner,owner_network,profile_volume,control_volume,phase=sys.argv[1:]
before_raw,after_raw=sys.stdin.read().split('\n__FETANAGENT_AFTER__\n',1)
before=json.loads(before_raw); after=json.loads(after_raw)
try:
    if not re.fullmatch(r'[0-9a-f]{64}', new_owner) or phase not in {'created','running'}: raise RuntimeError()
    if set(before) != {'images','networks','volumes','holders'} or set(after) != set(before): raise RuntimeError()
    if before['images'] != after['images']: raise RuntimeError()
    def keyed(items,key):
        if not isinstance(items,list) or any(not isinstance(item,dict) or key not in item for item in items): raise RuntimeError()
        result={item[key]:item for item in items}
        if len(result)!=len(items): raise RuntimeError()
