    before_volumes=keyed(before['volumes'],'Name'); after_volumes=keyed(after['volumes'],'Name')
    if set(before_networks)!=set(after_networks) or set(before_volumes)!=set(after_volumes): raise RuntimeError()
    owner_ids=[key for key,value in before_networks.items() if value.get('Name')==owner_network]
    if len(owner_ids)!=1 or [key for key,value in after_networks.items() if value.get('Name')==owner_network] != owner_ids: raise RuntimeError()
    owner_id=owner_ids[0]
    for key in before_networks:
        old=copy.deepcopy(before_networks[key]); new=copy.deepcopy(after_networks[key])
        old_endpoints=old.pop('Containers',{}) or {}; new_endpoints=new.pop('Containers',{}) or {}
        old_status=old.pop('Status',None); new_status=new.pop('Status',None)
        if old!=new or not isinstance(old_endpoints,dict) or not isinstance(new_endpoints,dict): raise RuntimeError()
        if phase=='created' or key!=owner_id:
            if old_endpoints!=new_endpoints or old_status!=new_status: raise RuntimeError()
            continue
        if new_owner in old_endpoints or set(new_endpoints)!=set(old_endpoints)|{new_owner}: raise RuntimeError()
        if any(new_endpoints[item]!=old_endpoints[item] for item in old_endpoints): raise RuntimeError()
        endpoint=new_endpoints[new_owner]
        if not isinstance(endpoint,dict) or set(endpoint)!={'Name','EndpointID','MacAddress','IPv4Address','IPv6Address'}: raise RuntimeError()
        if endpoint['Name']!='fetanagent-staging-beta-owner-control-1': raise RuntimeError()
        if not re.fullmatch(r'[0-9a-f]{64}',endpoint['EndpointID'] or ''): raise RuntimeError()
        if not re.fullmatch(r'(?:[0-9a-f]{2}:){5}[0-9a-f]{2}',endpoint['MacAddress'] or ''): raise RuntimeError()
        ipv4=ipaddress.ip_interface(endpoint['IPv4Address']); ipv6=ipaddress.ip_interface(endpoint['IPv6Address'])
        if ipv4.version!=4 or ipv6.version!=6: raise RuntimeError()
        subnets=[]
        for config in (old.get('IPAM') or {}).get('Config') or []:
            if isinstance(config,dict) and isinstance(config.get('Subnet'),str): subnets.append(ipaddress.ip_network(config['Subnet']))
        if not any(ipv4.ip in subnet for subnet in subnets if subnet.version==4): raise RuntimeError()
        if not any(ipv6.ip in subnet for subnet in subnets if subnet.version==6): raise RuntimeError()
        if not isinstance(old_status,dict) or not isinstance(new_status,dict): raise RuntimeError()
        if set(old_status)!={'IPAM'} or set(new_status)!={'IPAM'}: raise RuntimeError()
        old_ipam=old_status['IPAM']; new_ipam=new_status['IPAM']
        if not isinstance(old_ipam,dict) or not isinstance(new_ipam,dict): raise RuntimeError()
        if set(old_ipam)!={'Subnets'} or set(new_ipam)!={'Subnets'}: raise RuntimeError()
        old_status_subnets=old_ipam['Subnets']; new_status_subnets=new_ipam['Subnets']
        if not isinstance(old_status_subnets,dict) or not isinstance(new_status_subnets,dict): raise RuntimeError()
        if set(old_status_subnets)!=set(new_status_subnets): raise RuntimeError()
        expected_changed=[]
        for address in (ipv4,ipv6):
            matches=[name for name in old_status_subnets if address.ip in ipaddress.ip_network(name)]
            if len(matches)!=1: raise RuntimeError()
            expected_changed.append(matches[0])
        if len(set(expected_changed))!=2: raise RuntimeError()
        for name in old_status_subnets:
            old_counters=old_status_subnets[name]; new_counters=new_status_subnets[name]
            if not isinstance(old_counters,dict) or not isinstance(new_counters,dict): raise RuntimeError()
            if set(old_counters)!={'IPsInUse','DynamicIPsAvailable'} or set(new_counters)!=set(old_counters): raise RuntimeError()
            if any(isinstance(value,bool) or not isinstance(value,int) or value<0 for value in (*old_counters.values(),*new_counters.values())): raise RuntimeError()
            if name in expected_changed:
                if new_counters['IPsInUse']!=old_counters['IPsInUse']+1: raise RuntimeError()
                if new_counters['DynamicIPsAvailable']!=old_counters['DynamicIPsAvailable']-1: raise RuntimeError()
            elif old_counters!=new_counters: raise RuntimeError()
    if before_volumes!=after_volumes: raise RuntimeError()
    if not isinstance(before['holders'],dict) or not isinstance(after['holders'],dict): raise RuntimeError()
    if set(before['holders'])!=set(after['holders']) or set(before['holders'])!=set(before_volumes): raise RuntimeError()
    for name in before['holders']:
        old=before['holders'][name]; new=after['holders'][name]
        if name==control_volume:
            if old!=[] or new!=[new_owner]: raise RuntimeError()
        elif old!=new: raise RuntimeError()
    if before['holders'].get(profile_volume)!=[] or after['holders'].get(profile_volume)!=[]: raise RuntimeError()
except Exception:
    raise SystemExit(1)
PY
}

# Post-replacement comparator. The immutable 8f comparator above remains the
# pre-mutation authority. This successor permits only the exact failed-a51
# image residue plus the new attested runtime descriptor, and the exact
# old->new customer endpoint/holder swap.
require_exact_successor_inventory_delta_inline_reference() {
  local before="$1" after="$2" new_owner="$3" old_customer="$4" new_customer="$5" new_image="$6" failed_image="$7"
  printf '%s\n__FETANAGENT_AFTER__\n%s\n' "$before" "$after" |
    env -i PATH="$SAFE_PATH" python3 -I /dev/fd/3 \
      "$new_owner" "$OWNER_NETWORK" "$CONTROL_VOLUME" "$PROFILE_VOLUME" \
      "$old_customer" "$new_customer" "$new_image" "$failed_image" \
      "$FAILED_OCI_IDENTITY_CORRECTION_RELEASE" "$FAILED_OWNER_DELTA_CORRECTION_RELEASE" 3<<'PY'
import copy, ipaddress, json, re, sys
new_owner, owner_network, control_volume, profile_volume, old_customer, new_customer, new_image, failed_image, release, failed_release = sys.argv[1:]
before_raw, after_raw = sys.stdin.read().split('\n__FETANAGENT_AFTER__\n', 1)
before = json.loads(before_raw); after = json.loads(after_raw)
def keyed(items, key):
    if not isinstance(items, list) or any(not isinstance(item, dict) or key not in item for item in items): raise RuntimeError()
    result = {item[key]: item for item in items}
    if len(result) != len(items): raise RuntimeError()
    return result
try:
    if any(not re.fullmatch(r'[0-9a-f]{64}', value) for value in (new_owner, old_customer, new_customer)): raise RuntimeError()
    if any(not re.fullmatch(r'sha256:[0-9a-f]{64}', value) for value in (new_image, failed_image)): raise RuntimeError()
    if new_image == failed_image: raise RuntimeError()
    if set(before) != {'images','networks','volumes','holders'} or set(after) != set(before): raise RuntimeError()
    old_images = keyed(before['images'], 'Id'); new_images = keyed(after['images'], 'Id')
    if new_image in old_images or failed_image in old_images: raise RuntimeError()
    if set(new_images) != set(old_images) | {failed_image, new_image}: raise RuntimeError()
    if any(new_images[key] != old_images[key] for key in old_images): raise RuntimeError()
    added = new_images[new_image]
    config = added.get('Config') or {}
    if added.get('Id') != new_image or (added.get('Descriptor') or {}).get('digest') != new_image: raise RuntimeError()
    if added.get('RepoTags') != [f'fetanagent-customer-web:{release[:12]}']: raise RuntimeError()
    if added.get('RepoDigests') != [f'fetanagent-customer-web@{new_image}']: raise RuntimeError()
    if config.get('User') != '10001:10001' or config.get('Cmd') != ['node','apps/customer-web/dist/index.js']: raise RuntimeError()
    if (config.get('Labels') or {}).get('org.opencontainers.image.revision') != release: raise RuntimeError()
    failed = new_images[failed_image]
    failed_config = failed.get('Config') or {}
    if failed.get('Id') != failed_image or (failed.get('Descriptor') or {}).get('digest') != failed_image: raise RuntimeError()
    if failed.get('RepoTags') != [f'fetanagent-customer-web:{failed_release[:12]}']: raise RuntimeError()
    if failed.get('RepoDigests') != [f'fetanagent-customer-web@{failed_image}']: raise RuntimeError()
    if failed_config.get('User') != '10001:10001' or failed_config.get('Cmd') != ['node','apps/customer-web/dist/index.js']: raise RuntimeError()
    if failed_config.get('Entrypoint') != ['docker-entrypoint.sh'] or failed_config.get('WorkingDir') != '/workspace': raise RuntimeError()
    if (failed_config.get('Labels') or {}).get('org.opencontainers.image.revision') != failed_release: raise RuntimeError()
    old_networks = keyed(before['networks'], 'Id'); new_networks = keyed(after['networks'], 'Id')
    if set(old_networks) != set(new_networks): raise RuntimeError()
    owner_ids = [key for key, value in old_networks.items() if value.get('Name') == owner_network]
    if len(owner_ids) != 1 or [key for key, value in new_networks.items() if value.get('Name') == owner_network] != owner_ids: raise RuntimeError()
    owner_id = owner_ids[0]; customer_swaps = 0
    for key in old_networks:
        old = copy.deepcopy(old_networks[key]); new = copy.deepcopy(new_networks[key])
        old_endpoints = old.pop('Containers', {}) or {}; new_endpoints = new.pop('Containers', {}) or {}
        old_status = old.pop('Status', None); new_status = new.pop('Status', None)
        if old != new or not isinstance(old_endpoints, dict) or not isinstance(new_endpoints, dict): raise RuntimeError()
        if key == owner_id:
            expected_endpoints = set(old_endpoints) | {new_owner}
            if old_customer in old_endpoints or new_customer in new_endpoints:
                if old_customer not in old_endpoints or new_customer not in new_endpoints: raise RuntimeError()
                if new_customer in old_endpoints or old_customer in new_endpoints: raise RuntimeError()
                expected_endpoints = (expected_endpoints - {old_customer}) | {new_customer}
                old_customer_endpoint = old_endpoints[old_customer]
                new_customer_endpoint = new_endpoints[new_customer]
                if not isinstance(old_customer_endpoint, dict) or not isinstance(new_customer_endpoint, dict): raise RuntimeError()
                if set(old_customer_endpoint) != {'Name','EndpointID','MacAddress','IPv4Address','IPv6Address'} or set(new_customer_endpoint) != set(old_customer_endpoint): raise RuntimeError()
                if old_customer_endpoint.get('Name') != 'fetanagent-staging-beta-customer-web-1' or new_customer_endpoint.get('Name') != old_customer_endpoint.get('Name'): raise RuntimeError()
                customer_swaps += 1
            if new_owner in old_endpoints or set(new_endpoints) != expected_endpoints: raise RuntimeError()
            if any(new_endpoints[item] != old_endpoints[item] for item in old_endpoints if item != old_customer): raise RuntimeError()
            endpoint = new_endpoints[new_owner]
            if not isinstance(endpoint, dict) or endpoint.get('Name') != 'fetanagent-staging-beta-owner-control-1': raise RuntimeError()
            addresses = [ipaddress.ip_interface(endpoint[name]) for name in ('IPv4Address','IPv6Address')]
            if {address.version for address in addresses} != {4,6}: raise RuntimeError()
            if not isinstance(old_status, dict) or not isinstance(new_status, dict): raise RuntimeError()
            old_subnets = (old_status.get('IPAM') or {}).get('Subnets'); new_subnets = (new_status.get('IPAM') or {}).get('Subnets')
            if not isinstance(old_subnets, dict) or set(old_subnets) != set(new_subnets or {}): raise RuntimeError()
            changed = []
            for address in addresses:
                matches = [name for name in old_subnets if address.ip in ipaddress.ip_network(name)]
                if len(matches) != 1: raise RuntimeError()
                changed.append(matches[0])
            for name in old_subnets:
                old_count = old_subnets[name]; new_count = new_subnets[name]
                if name in changed:
                    if new_count.get('IPsInUse') != old_count.get('IPsInUse') + 1: raise RuntimeError()
                    if new_count.get('DynamicIPsAvailable') != old_count.get('DynamicIPsAvailable') - 1: raise RuntimeError()
                elif old_count != new_count: raise RuntimeError()
        elif old_customer in old_endpoints or new_customer in new_endpoints:
            if old_customer not in old_endpoints or new_customer not in new_endpoints: raise RuntimeError()
            if new_customer in old_endpoints or old_customer in new_endpoints: raise RuntimeError()
            if set(new_endpoints) != (set(old_endpoints) - {old_customer}) | {new_customer}: raise RuntimeError()
            if any(new_endpoints[item] != old_endpoints[item] for item in old_endpoints if item != old_customer): raise RuntimeError()
            old_ep = old_endpoints[old_customer]; new_ep = new_endpoints[new_customer]
            if not isinstance(old_ep, dict) or not isinstance(new_ep, dict): raise RuntimeError()
            if old_ep.get('Name') != 'fetanagent-staging-beta-customer-web-1' or new_ep.get('Name') != old_ep.get('Name'): raise RuntimeError()
            if old_status != new_status: raise RuntimeError()
            customer_swaps += 1
        elif old_endpoints != new_endpoints or old_status != new_status:
            raise RuntimeError()
    if customer_swaps != 1: raise RuntimeError()
    if keyed(before['volumes'], 'Name') != keyed(after['volumes'], 'Name'): raise RuntimeError()
    if not isinstance(before['holders'], dict) or set(before['holders']) != set(after['holders']): raise RuntimeError()
    for name, old_holders in before['holders'].items():
        new_holders = after['holders'][name]
        if name == control_volume:
            if old_holders != [] or new_holders != [new_owner]: raise RuntimeError()
        elif old_customer in old_holders:
            if new_holders != sorted((set(old_holders) - {old_customer}) | {new_customer}): raise RuntimeError()
        elif old_holders != new_holders: raise RuntimeError()
    if before['holders'].get(profile_volume) != [] or after['holders'].get(profile_volume) != []: raise RuntimeError()
except Exception:
    raise SystemExit(1)
PY
}

require_exact_successor_inventory_delta() {
