      "$customer_inventory" "$CUSTOMER_WEB_RUNTIME_IMAGE_ID" \
      "$FAILED_OWNER_DELTA_CORRECTION_RUNTIME_DESCRIPTOR_ID" "$PROVIDED_CUSTOMER_WEB_IMAGE_ID" \
