    "$FAILED_RUNNING_STATUS_BRIDGE_DOCKER_SNAPSHOT_SIZE" "$FAILED_RUNNING_STATUS_BRIDGE_DOCKER_SNAPSHOT_SHA256") || return 1
  require_successor_endpoint_phase_boundary "$phase"
}

