prepare_record_digests() {
  BRIDGE_INTENT_SHA256="$(sha256sum -- "$BRIDGE_WORK_ROOT/intent-v1" | awk '{print $1}')" || return 1
  [[ "$BRIDGE_INTENT_SHA256" =~ ^[0-9a-f]{64}$ ]] || return 1
  if [[ -e "$BRIDGE_WORK_ROOT/customer-web-replacement-v1" && ! -L "$BRIDGE_WORK_ROOT/customer-web-replacement-v1" ]]; then
    CUSTOMER_WEB_REPLACEMENT_RECORD_SHA256="$(sha256sum -- "$BRIDGE_WORK_ROOT/customer-web-replacement-v1" | awk '{print $1}')" || return 1
    [[ "$CUSTOMER_WEB_REPLACEMENT_RECORD_SHA256" =~ ^[0-9a-f]{64}$ ]] || return 1
  fi
  if [[ -e "$BRIDGE_WORK_ROOT/replacement-owner-v1" && ! -L "$BRIDGE_WORK_ROOT/replacement-owner-v1" ]]; then
    REPLACEMENT_RECORD_SHA256="$(sha256sum -- "$BRIDGE_WORK_ROOT/replacement-owner-v1" | awk '{print $1}')" || return 1
    [[ "$REPLACEMENT_RECORD_SHA256" =~ ^[0-9a-f]{64}$ ]] || return 1
  fi
  if [[ -e "$BRIDGE_WORK_ROOT/start-owner-v1" && ! -L "$BRIDGE_WORK_ROOT/start-owner-v1" ]]; then
    START_RECORD_SHA256="$(sha256sum -- "$BRIDGE_WORK_ROOT/start-owner-v1" | awk '{print $1}')" || return 1
    [[ "$START_RECORD_SHA256" =~ ^[0-9a-f]{64}$ ]] || return 1
  fi
}

require_bridge_completed() {
  local path="$BRIDGE_WORK_ROOT/completed-v1"
  prepare_record_digests || return 1
  [[ ! -L "$path" && -f "$path" && "$(realpath -- "$path")" == "$path" &&
    "$(stat --format='%U:%G:%a:%h' "$path")" == 'root:root:600:1' ]] || return 1
  cmp -s -- "$path" <(expected_bridge_completed)
}

acquire_staging_mutation_lock() {
  local lock_status
  coproc H14_BRIDGE_LOCK_HOLDER {
    exec env -i PATH="$SAFE_PATH" python3 -I /dev/fd/3 \
      "$LOCK_ROOT" "$LOCK" 3<<'PY'
import fcntl
import os
import stat
import sys

root, path = sys.argv[1:]
if path != f'{root}/mutation.lock' or os.path.realpath(os.path.dirname(root)) != os.path.dirname(root):
    raise SystemExit(1)
parent = os.path.dirname(root)
parent_value = os.lstat(parent)
if not stat.S_ISDIR(parent_value.st_mode):
    raise SystemExit(1)
created_root = False
try:
    os.mkdir(root, 0o700)
    created_root = True
except FileExistsError:
    pass
root_descriptor = os.open(root, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
try:
    if created_root:
        os.fchown(root_descriptor, 0, 0)
        os.fchmod(root_descriptor, 0o700)
        os.fsync(root_descriptor)
        parent_descriptor = os.open(parent, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
        try:
            os.fsync(parent_descriptor)
        finally:
            os.close(parent_descriptor)
    root_value = os.fstat(root_descriptor)
    root_named = os.lstat(root)
    if (
        not stat.S_ISDIR(root_value.st_mode)
        or (root_value.st_dev, root_value.st_ino) != (root_named.st_dev, root_named.st_ino)
        or (root_value.st_uid, root_value.st_gid, stat.S_IMODE(root_value.st_mode)) != (0, 0, 0o700)
        or os.path.realpath(root) != root
    ):
        raise SystemExit(1)
    flags = os.O_RDWR | os.O_NOFOLLOW | os.O_CLOEXEC
    created_lock = False
    try:
        lock_descriptor = os.open('mutation.lock', flags, dir_fd=root_descriptor)
    except FileNotFoundError:
        try:
            lock_descriptor = os.open(
                'mutation.lock', flags | os.O_CREAT | os.O_EXCL, 0o600, dir_fd=root_descriptor,
            )
            created_lock = True
        except FileExistsError:
            raise SystemExit(1)
    try:
        if created_lock:
            os.fchown(lock_descriptor, 0, 0)
            os.fchmod(lock_descriptor, 0o600)
            os.fsync(lock_descriptor)
            os.fsync(root_descriptor)
        before = os.fstat(lock_descriptor)
        named = os.stat('mutation.lock', dir_fd=root_descriptor, follow_symlinks=False)
        if (
            not stat.S_ISREG(before.st_mode)
            or (before.st_dev, before.st_ino) != (named.st_dev, named.st_ino)
            or (before.st_uid, before.st_gid, stat.S_IMODE(before.st_mode), before.st_nlink) != (0, 0, 0o600, 1)
            or before.st_size != 0
            or os.path.realpath(path) != path
        ):
            raise SystemExit(1)
        try:
            fcntl.flock(lock_descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            raise SystemExit(73)
        after = os.fstat(lock_descriptor)
        named_after = os.stat('mutation.lock', dir_fd=root_descriptor, follow_symlinks=False)
        if (
            (after.st_dev, after.st_ino, after.st_mode, after.st_uid, after.st_gid,
             after.st_nlink, after.st_size, after.st_mtime_ns)
            != (before.st_dev, before.st_ino, before.st_mode, before.st_uid, before.st_gid,
                before.st_nlink, before.st_size, before.st_mtime_ns)
            or (after.st_dev, after.st_ino) != (named_after.st_dev, named_after.st_ino)
        ):
            raise SystemExit(1)
        print(f'locked:{after.st_dev}:{after.st_ino}', flush=True)
        sys.stdin.buffer.read()
    finally:
        os.close(lock_descriptor)
finally:
    os.close(root_descriptor)
PY
  }
  LOCK_HOLDER_PROCESS_ID="$H14_BRIDGE_LOCK_HOLDER_PID"
  LOCK_STATUS_FD="${H14_BRIDGE_LOCK_HOLDER[0]}"
  LOCK_CONTROL_FD="${H14_BRIDGE_LOCK_HOLDER[1]}"
  if ! IFS= read -r lock_status <&"$LOCK_STATUS_FD"; then
    exec {LOCK_CONTROL_FD}>&- || true
    wait "$LOCK_HOLDER_PROCESS_ID" || true
    return 1
  fi
  exec {LOCK_STATUS_FD}<&-
  [[ "$lock_status" =~ ^locked:[0-9]+:[0-9]+$ ]]
}

release_staging_mutation_lock() {
  exec {LOCK_CONTROL_FD}>&- || return 1
  wait "$LOCK_HOLDER_PROCESS_ID" || return 1
  unset LOCK_HOLDER_PROCESS_ID LOCK_STATUS_FD LOCK_CONTROL_FD
}

require_exact_droplet || die 'the DigitalOcean Droplet identity is not exact'
customer_web_normalized_contract_digest() {
  local container_id="$1"
  [[ "$container_id" =~ ^[0-9a-f]{64}$ ]] || return 1
  docker_local container inspect "$container_id" |
    env -i PATH="$SAFE_PATH" python3 -I /dev/fd/3 "$container_id" 3<<'PY'
import hashlib
import json
import sys

expected = sys.argv[1]
payload = json.load(sys.stdin)
if not isinstance(payload, list) or len(payload) != 1 or payload[0].get('Id') != expected:
    raise SystemExit(1)
item = payload[0]
config = item.get('Config'); host = item.get('HostConfig'); mounts = item.get('Mounts')
if not isinstance(config, dict) or not isinstance(host, dict) or not isinstance(mounts, list):
    raise SystemExit(1)
labels = dict(config.get('Labels') or {})
for key in ('com.docker.compose.config-hash', 'com.docker.compose.image', 'org.opencontainers.image.revision'):
    labels.pop(key, None)
contract = {
    'version': 'fetanagent-customer-web-replacement-normalized-v1',
    'Name': item.get('Name'),
    'Config.User': config.get('User'),
    'Config.Cmd': config.get('Cmd'),
    'Config.Env': config.get('Env'),
    'HostConfig': {key: host.get(key) for key in (
        'ReadonlyRootfs', 'CapAdd', 'CapDrop', 'SecurityOpt', 'RestartPolicy',
        'NetworkMode', 'PortBindings', 'PidsLimit', 'Memory', 'NanoCpus')},
    'Mounts': sorted(mounts, key=lambda value: json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=True)),
    'Config.Labels': labels,
}

encoded = (json.dumps(contract, sort_keys=True, separators=(',', ':'), ensure_ascii=True) + '\n').encode('ascii')
print(hashlib.sha256(encoded).hexdigest())
PY
}

customer_web_semantic_v2_digest() {
  local container_id="$1"
  [[ "$container_id" =~ ^[0-9a-f]{64}$ ]] || return 1
  docker_local container inspect "$container_id" |
    env -i PATH="$SAFE_PATH" python3 -I /dev/fd/3 \
      "$container_id" "$PROJECT_NAME" "$OWNER_NETWORK" "$CLAIM_ROOT" \
      "$ADOPTED_CUSTOMER_WEB_COMPOSE_CONFIG_SHA256" \
      "$FAILED_OCI_IDENTITY_CORRECTION_RUNTIME_DESCRIPTOR_ID" \
      "$FAILED_OCI_IDENTITY_CORRECTION_RELEASE" 3<<'PY'
import hashlib
import json
import sys

(
    expected_id, project, owner_network, claim_root, compose_config_sha,
    image_descriptor, replacement_release,
) = sys.argv[1:]
try:
    payload = json.load(sys.stdin)
    if not isinstance(payload, list) or len(payload) != 1 or payload[0].get('Id') != expected_id:
        raise RuntimeError()
    item = payload[0]
    config = item.get('Config')
    host = item.get('HostConfig')
    mounts = item.get('Mounts')
    network_settings = item.get('NetworkSettings')
    if not all(isinstance(value, expected) for value, expected in (
        (config, dict), (host, dict), (mounts, list), (network_settings, dict),
    )):
        raise RuntimeError()
    labels = config.get('Labels') or {}
    stable_label_keys = (
        'com.docker.compose.container-number',
        'com.docker.compose.depends_on',
        'com.docker.compose.oneoff',
        'com.docker.compose.project',
        'com.docker.compose.service',
        'org.opencontainers.image.title',
    )
    provenance_label_keys = (
        'com.docker.compose.config-hash',
        'com.docker.compose.image',
        'com.docker.compose.project.config_files',
        'com.docker.compose.project.environment_file',
        'com.docker.compose.project.working_dir',
        'com.docker.compose.replace',
        'com.docker.compose.version',
        'org.opencontainers.image.revision',
    )
    if set(labels) != set(stable_label_keys) | set(provenance_label_keys):
        raise RuntimeError()
    expected_stable = {
        'com.docker.compose.container-number': '1',
        'com.docker.compose.depends_on': '',
        'com.docker.compose.oneoff': 'False',
        'com.docker.compose.project': project,
        'com.docker.compose.service': 'customer-web',
        'org.opencontainers.image.title': 'fetanagent-customer-web',
    }
    expected_provenance = {
        'com.docker.compose.config-hash': compose_config_sha,
        'com.docker.compose.image': image_descriptor,
        'com.docker.compose.project.config_files': f'{claim_root}/compose.staging-beta.yaml',
        'com.docker.compose.project.environment_file': '/dev/null',
        'com.docker.compose.project.working_dir': claim_root,
        'com.docker.compose.replace': 'customer-web-1',
        'com.docker.compose.version': '5.1.4',
        'org.opencontainers.image.revision': replacement_release,
    }
    if any(labels.get(key) != value for key, value in (expected_stable | expected_provenance).items()):
        raise RuntimeError()
    environment = config.get('Env')
    if not isinstance(environment, list) or any(not isinstance(value, str) or '=' not in value for value in environment):
        raise RuntimeError()
    if len(environment) != len(set(value.split('=', 1)[0] for value in environment)):
        raise RuntimeError()
    networks = network_settings.get('Networks') or {}
    if set(networks) != {owner_network} or network_settings.get('Ports') not in ({}, None):
        raise RuntimeError()
    contract = {
        'version': 'fetanagent-customer-web-reconciliation-semantic-v2',
        'Name': item.get('Name'),
        'Config.User': config.get('User'),
        'Config.Cmd': config.get('Cmd'),
        'Config.Entrypoint': config.get('Entrypoint'),
        'Config.WorkingDir': config.get('WorkingDir'),
        'Config.Env': sorted(environment),
        'Config.Labels': {key: labels[key] for key in stable_label_keys},
        'HostConfig': {key: host.get(key) for key in (
            'ReadonlyRootfs', 'Privileged', 'Init', 'CapAdd', 'CapDrop',
            'SecurityOpt', 'RestartPolicy', 'NetworkMode', 'PortBindings',
            'PublishAllPorts', 'PidsLimit', 'Memory', 'NanoCpus', 'Tmpfs',
        )},
        'Mounts': sorted(mounts, key=lambda value: json.dumps(
            value, sort_keys=True, separators=(',', ':'), ensure_ascii=True,
        )),
        'NetworkNames': sorted(networks),
        'NetworkPorts': network_settings.get('Ports'),
    }
    encoded = (json.dumps(
        contract, sort_keys=True, separators=(',', ':'), ensure_ascii=True,
    ) + '\n').encode('ascii')
    print(hashlib.sha256(encoded).hexdigest())
except Exception:
    raise SystemExit(1)
PY
}

require_customer_web_security_contract() {
  local container_id="$1" expected_network="$OWNER_NETWORK"
  docker_local container inspect "$container_id" |
    env -i PATH="$SAFE_PATH" python3 -I /dev/fd/3 "$container_id" "$expected_network" 3<<'PY'
import json, sys
expected, expected_network = sys.argv[1:]
try:
    payload = json.load(sys.stdin)
    if not isinstance(payload, list) or len(payload) != 1 or payload[0].get('Id') != expected: raise RuntimeError()
    item = payload[0]; config = item.get('Config') or {}; host = item.get('HostConfig') or {}; networks = (item.get('NetworkSettings') or {}).get('Networks') or {}
    if config.get('Entrypoint') != ['docker-entrypoint.sh']: raise RuntimeError()
    if config.get('WorkingDir') != '/workspace' or config.get('ExposedPorts') not in (None, {}): raise RuntimeError()
    if config.get('Healthcheck') != {
        'Test':['CMD','node','-e',"fetch('http://127.0.0.1:3003/readyz').then((response) => process.exit(response.ok ? 0 : 1)).catch(() => process.exit(1))"],
        'Interval':30000000000,'Timeout':3000000000,'StartPeriod':15000000000,'Retries':3,
    }: raise RuntimeError()
    if host.get('Privileged') is not False or host.get('ReadonlyRootfs') is not True or host.get('Init') is not True: raise RuntimeError()
    if host.get('CapAdd') not in (None, []) or host.get('CapDrop') != ['ALL']: raise RuntimeError()
    if host.get('SecurityOpt') != ['no-new-privileges:true']: raise RuntimeError()
    if host.get('Tmpfs') != {'/tmp':'rw,noexec,nosuid,size=32m,mode=1777'}: raise RuntimeError()
    if host.get('PidsLimit') != 128 or host.get('Memory') != 268435456 or host.get('NanoCpus') != 500000000: raise RuntimeError()
    if host.get('PortBindings') not in (None, {}) or len(networks) != 1: raise RuntimeError()
    if next(iter(networks)) != expected_network: raise RuntimeError()
except Exception:
    raise SystemExit(1)
PY
}

capture_other_service_inventory() {
  # Service identity, rather than the ephemeral source container ID, keeps this
  # guard stable across the one explicitly authorized customer-web replacement.
  capture_non_owner_inventory | awk -F'|' '$2 != "customer-web"'
}

require_other_service_inventory_exact() {
  local current
  current="$(capture_other_service_inventory)" || return 1
  [[ "$(printf '%s\n' "$current" | sha256sum | awk '{print $1}')" == "$SOURCE_OTHER_SERVICE_INVENTORY_SHA256" ]] || return 1
  [[ "$(container_full_ids_for_service gateway)" == "$SOURCE_GATEWAY_CONTAINER_ID" ]] || return 1
  [[ "$(container_full_ids_for_service bot)" == "$SOURCE_BOT_CONTAINER_ID" ]] || return 1
  [[ "$(container_full_ids_for_service beta-admission)" == "$SOURCE_BETA_CONTAINER_ID" ]]
}

require_owner_never_restarted() {
  [[ "$(docker_local container inspect "$CREATED_OWNER_CONTAINER_ID" --format '{{.Id}}|{{.State.Pid}}|{{.State.StartedAt}}|{{.RestartCount}}|{{.State.Status}}|{{if .State.Health}}{{.State.Health.Status}}{{end}}')" == \
    "$CREATED_OWNER_CONTAINER_ID|$SOURCE_OWNER_PID|$SOURCE_OWNER_STARTED_AT|0|running|healthy" ]]
}

require_source_customer_web_boundary() {
  local normalized state
  [[ "$(container_full_ids_for_service customer-web)" == "$SOURCE_CUSTOMER_WEB_CONTAINER_ID" ]] || return 1
  normalized="$(customer_web_normalized_contract_digest "$SOURCE_CUSTOMER_WEB_CONTAINER_ID")" || return 1
  [[ "$normalized" == "$SOURCE_CUSTOMER_WEB_NORMALIZED_SHA256" ]] || return 1
  require_customer_web_security_contract "$SOURCE_CUSTOMER_WEB_CONTAINER_ID" || return 1
  [[ "$(docker_local container inspect "$SOURCE_CUSTOMER_WEB_CONTAINER_ID" --format '{{.Image}}|{{.Config.Image}}|{{.Config.User}}|{{.RestartCount}}')" == \
    "$SOURCE_CUSTOMER_WEB_IMAGE_ID|fetanagent-customer-web:306818ca812b|10001:10001|0" ]] || return 1
  state="$(docker_local container inspect "$SOURCE_CUSTOMER_WEB_CONTAINER_ID" --format '{{.State.Status}}|{{.State.Running}}|{{if .State.Health}}{{.State.Health.Status}}{{end}}')" || return 1
  [[ "$state" == 'running|true|unhealthy' ]] || return 1
  [[ "$(docker_local container inspect "$SOURCE_CUSTOMER_WEB_CONTAINER_ID" --format '{{.State.Pid}}|{{.State.StartedAt}}')" == \
    "$SOURCE_CUSTOMER_WEB_PID|$SOURCE_CUSTOMER_WEB_STARTED_AT" ]] || return 1
  [[ "$(container_runtime_state_digest "$SOURCE_CUSTOMER_WEB_CONTAINER_ID")" == "$SOURCE_CUSTOMER_WEB_UNHEALTHY_RUNTIME_SHA256" ]] || return 1
  [[ "$(docker_local container inspect "$SOURCE_CUSTOMER_WEB_CONTAINER_ID" --format '{{range .Config.Env}}{{println .}}{{end}}' | LC_ALL=C sort | sha256sum | awk '{print $1}')" == "$SOURCE_CUSTOMER_WEB_ENV_SHA256" ]]
}

require_pre_customer_web_inventory() {
  require_adopted_customer_web_boundary || return 1
  require_other_service_inventory_exact
}

require_loaded_customer_web_image() {
  local image_id image_tag="fetanagent-customer-web:${FAILED_OCI_IDENTITY_CORRECTION_RELEASE:0:12}"
  require_customer_web_runtime_image_contract \
    "$ADOPTED_CUSTOMER_WEB_IMAGE_ARCHIVE" "$PROVIDED_CUSTOMER_WEB_IMAGE_ID" \
    "$CUSTOMER_WEB_RUNTIME_IMAGE_ID" "$image_tag" "$FAILED_OCI_IDENTITY_CORRECTION_RELEASE" || return 1
  image_id="$(docker_local image inspect "$image_tag" --format '{{.Id}}|{{.Descriptor.digest}}')" || return 1
  [[ "$image_id" == "$CUSTOMER_WEB_RUNTIME_IMAGE_ID|$CUSTOMER_WEB_RUNTIME_IMAGE_ID" ]] || return 1
  image_id="$CUSTOMER_WEB_RUNTIME_IMAGE_ID"
  CUSTOMER_WEB_IMAGE_ID="$image_id"
}

require_adopted_customer_web_boundary() {
  local customer_id normalized semantic state
  customer_id="$(container_full_ids_for_service customer-web)" || return 1
  [[ "$customer_id" == "$ADOPTED_CUSTOMER_WEB_CONTAINER_ID" ]] || return 1
  require_loaded_customer_web_image || return 1
  normalized="$(customer_web_normalized_contract_digest "$customer_id")" || return 1
  [[ "$normalized" == "$ADOPTED_CUSTOMER_WEB_V1_NORMALIZED_SHA256" &&
    "$normalized" != "$SOURCE_CUSTOMER_WEB_NORMALIZED_SHA256" ]] || return 1
  semantic="$(customer_web_semantic_v2_digest "$customer_id")" || return 1
  [[ "$semantic" == "$ADOPTED_CUSTOMER_WEB_SEMANTIC_V2_SHA256" ]] || return 1
  require_customer_web_security_contract "$customer_id" || return 1
  [[ "$(docker_local container inspect "$customer_id" --format '{{.Image}}|{{.Config.Image}}|{{.Config.User}}|{{.RestartCount}}|{{json .NetworkSettings.Ports}}|{{json .HostConfig.PortBindings}}')" == \
    "$CUSTOMER_WEB_IMAGE_ID|fetanagent-customer-web:${FAILED_OCI_IDENTITY_CORRECTION_RELEASE:0:12}|10001:10001|0|{}|{}" ]] || return 1
  state="$(docker_local container inspect "$customer_id" --format '{{.State.Status}}|{{.State.Running}}|{{if .State.Health}}{{.State.Health.Status}}{{end}}')" || return 1
  [[ "$state" == 'running|true|healthy' ]] || return 1
  [[ "$(docker_local container inspect "$customer_id" --format '{{.State.Pid}}|{{.State.StartedAt}}')" == \
    "$ADOPTED_CUSTOMER_WEB_PID|$ADOPTED_CUSTOMER_WEB_STARTED_AT" ]] || return 1
  [[ "$(container_runtime_state_digest "$customer_id")" == "$ADOPTED_CUSTOMER_WEB_RUNTIME_SHA256" ]] || return 1
  [[ "$(docker_local container inspect "$customer_id" --format '{{range .Config.Env}}{{println .}}{{end}}' | LC_ALL=C sort | sha256sum | awk '{print $1}')" == "$SOURCE_CUSTOMER_WEB_ENV_SHA256" ]] || return 1
  ! docker_local container inspect "$SOURCE_CUSTOMER_WEB_CONTAINER_ID" >/dev/null 2>&1 || return 1
  NEW_CUSTOMER_WEB_CONTAINER_ID="$customer_id"
}

require_replacement_customer_web_boundary() {
  require_adopted_customer_web_boundary
}

expected_customer_web_replacement_record() {
  printf '%s\n' \
    'version=2' \
    'contract=fetanagent-h14-customer-web-self-recovery-reconciliation-v2' \
    'state=healthy-replacement-adopted-without-lifecycle-mutation' \
    "replacement_implementation_sha=$FAILED_OCI_IDENTITY_CORRECTION_RELEASE" \
    "reconciliation_implementation_sha=$RECOVERY_RELEASE" \
    "source_customer_web_container_id=$SOURCE_CUSTOMER_WEB_CONTAINER_ID" \
    "source_customer_web_image_id=$SOURCE_CUSTOMER_WEB_IMAGE_ID" \
    "replacement_customer_web_container_id=$NEW_CUSTOMER_WEB_CONTAINER_ID" \
    "replacement_customer_web_image_id=$CUSTOMER_WEB_IMAGE_ID" \
    "replacement_customer_web_image_tag=fetanagent-customer-web:${FAILED_OCI_IDENTITY_CORRECTION_RELEASE:0:12}" \
    "source_customer_web_v1_normalized_sha256=$SOURCE_CUSTOMER_WEB_NORMALIZED_SHA256" \
    "replacement_customer_web_v1_normalized_sha256=$ADOPTED_CUSTOMER_WEB_V1_NORMALIZED_SHA256" \
    "replacement_customer_web_semantic_v2_sha256=$ADOPTED_CUSTOMER_WEB_SEMANTIC_V2_SHA256" \
    'customer_web_semantic_v2_contract=sorted-env-exact-fields-stable-label-allowlist-v2' \
    'v1_mismatch_classification=compose-lifecycle-provenance-and-ordering-noise' \
    "customer_web_image_archive_sha256=$PROVIDED_CUSTOMER_WEB_IMAGE_ARCHIVE_SHA256" \
    "customer_web_image_archive_size=$PROVIDED_CUSTOMER_WEB_IMAGE_ARCHIVE_SIZE" \
    "customer_web_image_id=$PROVIDED_CUSTOMER_WEB_IMAGE_ID" \
    "customer_web_runtime_descriptor_id=$CUSTOMER_WEB_RUNTIME_IMAGE_ID" \
    'customer_web_lifecycle_mutation=false-already-completed-by-replacement-implementation' \
    'docker_image_load_executed=false' \
    'docker_compose_executed=false' \
    'owner_lifecycle_mutation=false' \
    'other_service_lifecycle_mutation=false' \
    'financial_actions_mode=dry_run' \
    'kemerbet_executor_enabled=false' \
    'kemerbet_final_action_enabled=false' \
    'provider_action_enabled=false' \
    'transfer_enabled=false' \
    'amount_entry_enabled=false' \
    'money_moved=false'
}

require_customer_web_replacement_record() {
  local path="$BRIDGE_WORK_ROOT/customer-web-replacement-v1" line
  [[ ! -L "$path" && -f "$path" && "$(realpath -- "$path")" == "$path" &&
    "$(stat --format='%U:%G:%a:%h' "$path")" == 'root:root:600:1' ]] || return 1
  line="$(sed -n 's/^replacement_customer_web_container_id=//p' "$path")" || return 1
  [[ "$(grep -c '^replacement_customer_web_container_id=' "$path")" == '1' ]] || return 1
  line="replacement_customer_web_container_id=$line"
  [[ "$line" =~ ^replacement_customer_web_container_id=[0-9a-f]{64}$ ]] || return 1
  NEW_CUSTOMER_WEB_CONTAINER_ID="${line#replacement_customer_web_container_id=}"
  require_replacement_customer_web_boundary || return 1
  cmp -s -- "$path" <(expected_customer_web_replacement_record)
}

classify_customer_web_replacement_state() {
  require_adopted_customer_web_boundary || return 1
  printf '%s\n' complete
}

reconcile_customer_web_once() {
  local before_guard after_guard before_complete after_complete replacement_state
  require_bridge_intent || return 1
  require_failed_oci_identity_runtime || return 1
  require_other_service_inventory_exact || return 1
  before_guard="$(capture_other_service_inventory)" || return 1
  before_complete="$(capture_complete_docker_create_inventory)" || return 1
  require_owner_never_restarted || return 1
  require_loaded_customer_web_image || return 1
  require_prior_failed_recovery_claim || return 1
  require_failed_counter_runtime || return 1
  require_failed_customer_web_network_scope_runtime || return 1
  require_failed_network_scope_runtime || return 1
  require_failed_owner_delta_runtime || return 1
  require_failed_oci_identity_runtime || return 1
  replacement_state="$(classify_customer_web_replacement_state)" || return 1
  [[ "$replacement_state" == complete ]] || return 1
  require_replacement_customer_web_boundary || return 1
  require_failed_owner_delta_runtime || return 1
  require_failed_oci_identity_runtime || return 1
  ! docker_local container inspect "$SOURCE_CUSTOMER_WEB_CONTAINER_ID" >/dev/null 2>&1 || return 1
  after_guard="$(capture_other_service_inventory)" || return 1
  after_complete="$(capture_complete_docker_create_inventory)" || return 1
  [[ "$before_guard" == "$after_guard" ]] || return 1
  [[ "$before_complete" == "$after_complete" ]] || return 1
  require_other_service_inventory_exact || return 1
  require_owner_never_restarted
}

require_exact_recovery_source_anchors || die 'the immutable 001 terminal and Owner bundle source anchors are not exact'
require_original_bridge_namespace_absent ||
  die 'the immutable 001 Owner bridge namespace is no longer absent'
acquire_staging_mutation_lock || die 'the shared hardened staging mutation lock could not be acquired'
trap 'release_staging_mutation_lock || true' EXIT
require_no_other_mutator_processes || die 'another staging helper or recovery mutation is active'
require_active_grant_only || die 'the exact H14 helper grant is not active'
require_helper_exact || die 'the installed canonical H14 helper is not exact'

mapfile -t h14_values < <(load_exact_h14_and_mount_repair) || die 'the final canonical H14 or completed mount-repair ledger is invalid'
[[ "${#h14_values[@]}" -eq 8 ]] || die 'the H14 evidence attestation returned an invalid shape'
OLD_OWNER_CONTAINER_ID="${h14_values[0]}"
RETIRED_COORDINATOR_CONTAINER_ID="${h14_values[1]}"
OLD_OWNER_SEMANTIC_SHA256="${h14_values[2]}"
H14_NAMESPACE_DEVICE="${h14_values[3]}"
H14_NAMESPACE_INODE="${h14_values[4]}"
H14_EVIDENCE_TREE_SHA256="${h14_values[5]}"
MOUNT_REPAIR_INTENT_SHA256="${h14_values[6]}"
MOUNT_REPAIR_COMPLETION_SHA256="${h14_values[7]}"
[[ "$OLD_OWNER_CONTAINER_ID" =~ ^[0-9a-f]{64}$ && "$RETIRED_COORDINATOR_CONTAINER_ID" =~ ^[0-9a-f]{64}$ &&
  "$OLD_OWNER_SEMANTIC_SHA256" =~ ^[0-9a-f]{64}$ && "$H14_NAMESPACE_DEVICE" =~ ^[0-9]+$ &&
  "$H14_NAMESPACE_INODE" =~ ^[0-9]+$ && "$H14_EVIDENCE_TREE_SHA256" =~ ^[0-9a-f]{64}$ ]] ||
  die 'the H14 evidence values are malformed'

mapfile -t terminal_attestation_values < <(load_exact_terminal_attestation) ||
  die 'the explicit terminal-attestation completion is invalid'
[[ "${#terminal_attestation_values[@]}" -eq 19 &&
  "${terminal_attestation_values[0]}" =~ ^[0-9a-f]{64}$ &&
  "${terminal_attestation_values[1]}" =~ ^[0-9]+:[0-9]+$ &&
  "${terminal_attestation_values[2]}" =~ ^[0-9a-f]{64}$ &&
  "${terminal_attestation_values[3]}" =~ ^[0-9]+:[0-9]+$ &&
  "${terminal_attestation_values[4]}" =~ ^[0-9]+:[0-9]+$ &&
  "${terminal_attestation_values[5]}" =~ ^[0-9]+:[0-9]+$ &&
  "${terminal_attestation_values[6]}" =~ ^[0-9]+:[0-9]+$ &&
  "${terminal_attestation_values[7]}" =~ ^[0-9]+:[0-9]+$ &&
  "${terminal_attestation_values[8]}" =~ ^[0-9]+:[0-9]+$ &&
  "${terminal_attestation_values[9]}" =~ ^[0-9a-f]{64}$ &&
  "${terminal_attestation_values[10]}" =~ ^[0-9]+:[0-9]+$ &&
  "${terminal_attestation_values[11]}" =~ ^[0-9a-f]{64}$ &&
  "${terminal_attestation_values[12]}" =~ ^[1-9][0-9]{0,7}$ &&
  "${terminal_attestation_values[13]}" =~ ^[0-9]+:[0-9]+$ &&
  "${terminal_attestation_values[14]}" =~ ^[0-9a-f]{64}$ &&
  "${terminal_attestation_values[15]}" =~ ^[1-9][0-9]{0,7}$ &&
  "${terminal_attestation_values[16]}" =~ ^[0-9]+:[0-9]+$ &&
  "${terminal_attestation_values[17]}" =~ ^[0-9a-f]{64}$ &&
  "${terminal_attestation_values[18]}" =~ ^[1-9][0-9]{0,7}$ ]] ||
  die 'the terminal-attestation completion returned an invalid shape'
TERMINAL_ATTESTATION_COMPLETION_SHA256="${terminal_attestation_values[0]}"
ATTESTED_SUDOERS_DEV_INO="${terminal_attestation_values[1]}"
ATTESTED_SUDOERS_SHA256="${terminal_attestation_values[2]}"
ATTESTED_REPAIR_ROOT_DEV_INO="${terminal_attestation_values[3]}"
ATTESTED_CLAIM_ROOT_DEV_INO="${terminal_attestation_values[4]}"
ATTESTED_PROFILE_ROOT_DEV_INO="${terminal_attestation_values[5]}"
ATTESTED_CONTROL_ROOT_DEV_INO="${terminal_attestation_values[6]}"
ATTESTED_RECEIPT_ROOT_DEV_INO="${terminal_attestation_values[7]}"
ATTESTED_TERMINAL_MARKER_DEV_INO="${terminal_attestation_values[8]}"
ATTESTED_TERMINAL_MARKER_SHA256="${terminal_attestation_values[9]}"
ATTESTED_VALIDATOR_DEV_INO="${terminal_attestation_values[10]}"
ATTESTED_VALIDATOR_SHA256="${terminal_attestation_values[11]}"
ATTESTED_VALIDATOR_SIZE="${terminal_attestation_values[12]}"
ATTESTED_TERMINAL_BRIDGE_DEV_INO="${terminal_attestation_values[13]}"
ATTESTED_TERMINAL_BRIDGE_SHA256="${terminal_attestation_values[14]}"
ATTESTED_TERMINAL_BRIDGE_SIZE="${terminal_attestation_values[15]}"
ATTESTED_TERMINAL_MANIFEST_DEV_INO="${terminal_attestation_values[16]}"
ATTESTED_TERMINAL_MANIFEST_SHA256="${terminal_attestation_values[17]}"
ATTESTED_TERMINAL_MANIFEST_SIZE="${terminal_attestation_values[18]}"

PROFILE_ROOT="$(docker_local volume inspect --format '{{.Mountpoint}}' "$PROFILE_VOLUME")" ||
  die 'the attested KemerBet profile volume mountpoint is unavailable'
CONTROL_ROOT="$(docker_local volume inspect --format '{{.Mountpoint}}' "$CONTROL_VOLUME")" ||
  die 'the attested KemerBet control volume mountpoint is unavailable'
[[ "$PROFILE_ROOT" == /* && "$CONTROL_ROOT" == /* && "$PROFILE_ROOT" != "$CONTROL_ROOT" ]] ||
  die 'the attested KemerBet volume mountpoints are ambiguous'

mapfile -t bundle_values < <(claim_and_load_bundle_manifest) || die 'the staged canonical Owner-only bundle could not be claimed exactly'
[[ "${#bundle_values[@]}" -eq 6 ]] || die 'the claimed bundle manifest returned an invalid shape'
OWNER_IMAGE_TAG="${bundle_values[0]}"
OWNER_IMAGE_ID="${bundle_values[1]}"
OWNER_IMAGE_TAR_SHA256="${bundle_values[2]}"
OWNER_IMAGE_TAR_SIZE="${bundle_values[3]}"
CANONICAL_COMPOSE_SHA256="${bundle_values[4]}"
OWNER_BRIDGE_SCRIPT_SHA256="${bundle_values[5]}"
[[ "$OWNER_IMAGE_TAG" == "$OWNER_IMAGE" && "$OWNER_IMAGE_ID" =~ ^sha256:[0-9a-f]{64}$ &&
  "$OWNER_IMAGE_TAR_SHA256" =~ ^[0-9a-f]{64}$ && "$OWNER_IMAGE_TAR_SIZE" =~ ^[1-9][0-9]{0,11}$ &&
  "$CANONICAL_COMPOSE_SHA256" =~ ^[0-9a-f]{64}$ && "$OWNER_BRIDGE_SCRIPT_SHA256" =~ ^[0-9a-f]{64}$ ]] ||
  die 'the claimed bundle values are invalid'
[[ "$(sha256sum -- "$CLAIM_ROOT/$IMAGE_ARCHIVE_NAME" | awk '{print $1}')" == "$OWNER_IMAGE_TAR_SHA256" &&
  "$(stat --format='%s' "$CLAIM_ROOT/$IMAGE_ARCHIVE_NAME")" == "$OWNER_IMAGE_TAR_SIZE" &&
  "$(sha256sum -- "$CLAIM_ROOT/$COMPOSE_NAME" | awk '{print $1}')" == "$CANONICAL_COMPOSE_SHA256" &&
  "$OWNER_BRIDGE_SCRIPT_SHA256" == "$SOURCE_OWNER_BRIDGE_SHA256" &&
  "$OWNER_IMAGE_TAR_SHA256" == "$SOURCE_OWNER_TAR_SHA256" &&
  "$OWNER_IMAGE_TAR_SIZE" == "$SOURCE_OWNER_TAR_SIZE" &&
  "$CANONICAL_COMPOSE_SHA256" == "$SOURCE_OWNER_COMPOSE_SHA256" &&
  "$OWNER_IMAGE_ID" == "$SOURCE_OWNER_IMAGE_ID" ]] ||
  die 'a claimed bundle artifact changed'
inspect_image_archive || die 'the canonical Owner archive is not the exact reviewed OCI image graph'
require_original_bridge_namespace_absent ||
  die 'the immutable 001 Owner bridge namespace appeared during recovery preflight'
require_all_compose_inputs || die 'the exact existing staging Compose input files are unavailable or unsafe'
require_compose_contract_parses || die 'the canonical H14 Compose contract did not parse with the existing staging inputs'
require_owner_network || die 'the existing Owner-only network is not exact'
require_financial_gates_disabled || die 'a financial, executor, final-action, Amount, or Transfer gate is enabled'
require_no_host_chromium || die 'a host browser process exists before the Owner bridge'

NON_OWNER_INVENTORY="$(capture_non_owner_inventory)" ||
  die 'the unrelated project-service inventory is ambiguous or contains the retired coordinator'
if [[ -n "$NON_OWNER_INVENTORY" ]]; then
  NON_OWNER_INVENTORY_COUNT="$(awk 'END { print NR }' <<<"$NON_OWNER_INVENTORY")" ||
    die 'the unrelated project-service count could not be computed'
else
  NON_OWNER_INVENTORY_COUNT='0'
fi
NON_OWNER_INVENTORY_SHA256="$(printf '%s' "$NON_OWNER_INVENTORY" | sha256sum | awk '{print $1}')" ||
  die 'the unrelated project-service inventory digest could not be computed'
[[ "$NON_OWNER_INVENTORY_COUNT" =~ ^[0-9]+$ && "$NON_OWNER_INVENTORY_SHA256" =~ ^[0-9a-f]{64}$ ]] ||
  die 'the unrelated project-service inventory attestation is malformed'

require_prior_failed_runtime_ledger_absent || die 'the chained pre-51e failed runtime evidence is not exact'
require_failed_endpoint_phase_runtime || die 'the immutable 51e created-phase interruption evidence is not exact'
require_failed_running_status_runtime || die 'the immutable 8f running-phase interruption evidence is not exact'
require_failed_counter_runtime || die 'the immutable 020 empty pre-intent interruption evidence is not exact'
require_failed_customer_web_network_scope_runtime ||
  die 'CW-NET-SCOPE-002: the immutable failed 0110 empty pre-intent ledger changed'
require_failed_network_scope_runtime ||
  die 'OWNER-DELTA-002: the immutable failed 1f27 single-intent pre-mutation ledger changed'
require_failed_owner_delta_runtime ||
  die 'OCI-RUNTIME-ID-002: the immutable failed a51 intent-only runtime or loaded descriptor image changed'
require_failed_oci_identity_runtime ||
  die 'SEMANTIC-V2-002: the immutable failed 0ffc checkpoint or adopted healthy customer-web changed'
NEW_OWNER_CONTAINER_ID="$CREATED_OWNER_CONTAINER_ID"
create_or_discover_bridge_ledger || die 'the separate Owner-runtime bridge ledger is unsafe'
if [[ -e "$BRIDGE_WORK_ROOT/intent-v1" && ! -L "$BRIDGE_WORK_ROOT/intent-v1" ]]; then
  require_bridge_intent || die 'the durable Owner-runtime bridge intent changed'
else
  [[ "$BRIDGE_STATE" == 'installing' ]] || die 'a complete bridge is missing its intent'
  require_running_owner_boundary_before_successor_intent ||
    die 'the exact already-running Owner boundary changed before successor intent publication'
  publish_exact_record "$BRIDGE_WORK_ROOT/intent-v1" 0600 < <(expected_bridge_intent) ||
    die 'the Owner-runtime bridge intent could not be published durably'
fi
require_bridge_intent || die 'the published Owner-runtime bridge intent is invalid'

# The exact 0ffc predecessor durably replaced customer-web and Compose reported
# it healthy, but the v1 comparator rejected lifecycle/provenance noise before
# publishing its replacement record. This successor adopts that exact healthy
# container, reconciles it through the semantic v2 contract, and performs no
# Docker image, Compose, container, network, volume, or service mutation.
if [[ -e "$BRIDGE_WORK_ROOT/customer-web-replacement-v1" &&
  ! -L "$BRIDGE_WORK_ROOT/customer-web-replacement-v1" ]]; then
  require_customer_web_replacement_record ||
    die 'the durable customer-web replacement reconciliation record changed'
else
  [[ "$BRIDGE_STATE" == 'installing' ]] ||
    die 'a completed bridge is missing its customer-web reconciliation record'
  reconcile_customer_web_once ||
    die 'the exact customer-web semantic-v2 reconciliation failed closed'
  publish_exact_record "$BRIDGE_WORK_ROOT/customer-web-replacement-v1" 0600 \
    < <(expected_customer_web_replacement_record) ||
    die 'the customer-web reconciliation record could not be published durably'
  require_customer_web_replacement_record ||
    die 'the published customer-web reconciliation record is invalid'
fi
require_owner_never_restarted || die 'Owner lifecycle changed during customer-web reconciliation'
require_other_service_inventory_exact || die 'a non-customer service changed during customer-web reconciliation'
NON_OWNER_INVENTORY="$(capture_non_owner_inventory)" ||
  die 'the successor non-Owner inventory could not be captured'
NON_OWNER_INVENTORY_COUNT="$(awk 'END { print NR }' <<<"$NON_OWNER_INVENTORY")" ||
  die 'the successor non-Owner inventory count could not be computed'
NON_OWNER_INVENTORY_SHA256="$(printf '%s' "$NON_OWNER_INVENTORY" | sha256sum | awk '{print $1}')" ||
  die 'the successor non-Owner inventory digest could not be computed'
[[ "$NON_OWNER_INVENTORY_COUNT" == '5' && "$NON_OWNER_INVENTORY_SHA256" =~ ^[0-9a-f]{64}$ ]] ||
  die 'the successor non-Owner inventory is malformed'
require_non_owner_inventory_unchanged || die 'the successor non-Owner inventory changed after reconciliation'

# The exact 8f predecessor preserved the pre-create inventory, replacement
# identity, and start authorization. The API proof is reissued only after the
# exact customer-web replacement and retains the same read-only catalog query.
if [[ "$BRIDGE_STATE" != 'complete' ]]; then
  if [[ ! -e "$BRIDGE_WORK_ROOT/api-catalog-proof-v1" && ! -L "$BRIDGE_WORK_ROOT/api-catalog-proof-v1" ]]; then
    publish_exact_record "$BRIDGE_WORK_ROOT/api-catalog-proof-v1" 0600 < <(expected_api_catalog_proof) ||
      die 'the successor API catalog proof could not be published durably'
  fi
  require_api_catalog_proof || die 'the successor durable API catalog proof changed'
  ! docker_local container inspect "$OLD_OWNER_CONTAINER_ID" >/dev/null 2>&1 || die 'the removed historical Owner reappeared after durable intent'
  require_owner_image_contract || die 'the exact previously loaded image changed after durable intent'
  require_original_bridge_namespace_absent ||
    die 'the immutable 001 Owner bridge namespace appeared after durable recovery intent'
fi
prepare_record_digests || die 'the bridge intent digest is invalid'

if [[ ! -e "$BRIDGE_WORK_ROOT/docker-pre-create-v1" && ! -L "$BRIDGE_WORK_ROOT/docker-pre-create-v1" &&
  "$BRIDGE_STATE" != 'complete' ]]; then
  publish_exact_record "$BRIDGE_WORK_ROOT/docker-pre-create-v1" 0600 < <(emit_exact_nofollow_file \
    "$FAILED_RUNNING_STATUS_BRIDGE_DOCKER_SNAPSHOT" "$FAILED_RUNNING_STATUS_BRIDGE_DOCKER_SNAPSHOT_DEV_INO" \
    "$FAILED_RUNNING_STATUS_BRIDGE_DOCKER_SNAPSHOT_SIZE" "$FAILED_RUNNING_STATUS_BRIDGE_DOCKER_SNAPSHOT_SHA256") ||
    die 'the exact 8f pre-create Docker snapshot could not be republished durably'
fi
load_pre_create_docker_inventory || die 'the republished 8f pre-create Docker snapshot is unsafe or malformed'
cmp -s -- "$BRIDGE_WORK_ROOT/docker-pre-create-v1" <(emit_exact_nofollow_file \
  "$FAILED_RUNNING_STATUS_BRIDGE_DOCKER_SNAPSHOT" "$FAILED_RUNNING_STATUS_BRIDGE_DOCKER_SNAPSHOT_DEV_INO" \
  "$FAILED_RUNNING_STATUS_BRIDGE_DOCKER_SNAPSHOT_SIZE" "$FAILED_RUNNING_STATUS_BRIDGE_DOCKER_SNAPSHOT_SHA256") ||
  die 'the republished 8f pre-create Docker snapshot is not byte-exact'

if [[ "$BRIDGE_STATE" == 'complete' ]]; then
  require_customer_web_replacement_record || die 'the completed customer-web replacement record is invalid'
  load_replacement_record || die 'the completed bridge replacement record is invalid'
  prepare_record_digests || die 'the completed replacement digest is invalid'
  require_start_record || die 'the completed bridge start-intent record is invalid'
  prepare_record_digests || die 'the completed start-intent digest is invalid'
  require_bridge_completed || die 'the completed bridge ledger is invalid'
  if docker_local container inspect "$OLD_OWNER_CONTAINER_ID" >/dev/null 2>&1; then
    die 'the historical Owner reappeared beside completed bridge evidence'
  fi
  require_owner_image_contract || die 'the canonical Owner image changed after bridge completion'
  require_loaded_image_used_only_by "$NEW_OWNER_CONTAINER_ID" ||
    die 'the completed canonical Owner image has an unexpected user'
  require_non_owner_inventory_unchanged || die 'an unrelated project service changed after bridge completion'
  require_owner_contract "$NEW_OWNER_CONTAINER_ID" "$CANONICAL_H14" "$SOURCE_OWNER_LOADED_IMAGE_ID" || die 'the completed canonical Owner contract changed'
  [[ "$(docker_local container inspect "$NEW_OWNER_CONTAINER_ID" --format '{{.State.Status}}|{{if .State.Health}}{{.State.Health.Status}}{{end}}')" == 'running|healthy' ]] ||
    die 'the completed canonical Owner is not running and healthy'
  require_container_no_chromium "$NEW_OWNER_CONTAINER_ID" || die 'the completed Owner contains a browser process'
  require_runtime_boundary "$NEW_OWNER_CONTAINER_ID" || die 'the completed Owner/coordinator/volume/gate boundary changed'
  require_owner_network || die 'the completed Owner network contract changed'
  require_live_terminal_attestation_boundary "$NEW_OWNER_CONTAINER_ID" running ||
    die 'the live terminal-attestation boundary changed after bridge completion'
  require_prior_failed_runtime_ledger_absent ||
    die 'the immutable 911-absent and ff989-empty-pre-intent runtime evidence changed beside completion'
  require_failed_endpoint_phase_runtime ||
    die 'the immutable 51e created-phase interruption evidence changed beside completion'
  require_failed_running_status_runtime ||
    die 'the immutable 8f running-phase interruption evidence changed beside completion'
  require_failed_counter_runtime ||
    die 'the immutable 020 empty pre-intent interruption evidence changed beside completion'
  require_failed_customer_web_network_scope_runtime ||
    die 'CW-NET-SCOPE-003: the immutable failed 0110 empty pre-intent ledger changed beside completion'
  require_failed_network_scope_runtime ||
    die 'OWNER-DELTA-003: the immutable failed 1f27 single-intent pre-mutation ledger changed beside completion'
  require_failed_owner_delta_runtime ||
    die 'OCI-RUNTIME-ID-003: the immutable failed a51 intent-only runtime or descriptor residue changed beside completion'
  require_failed_oci_identity_runtime ||
    die 'SEMANTIC-V2-003: the immutable failed 0ffc checkpoint or adopted healthy customer-web changed beside completion'
  require_complete_owner_endpoint_phase_boundary running ||
    die 'the complete running-phase boundary changed beside completed replay'
  printf '%s\n' 'FetanAgent H14 customer-web recovery already valid: Owner unchanged; customer-web only; all financial gates disabled; no provider action and no money moved.'
  exit 0
fi

# The failed 0a correction durably loaded this exact image before failing closed.
# This chained correction only proves and consumes it; it never loads, retags,
# removes, or prunes an image.
require_owner_image_contract || die 'the exact previously loaded canonical Owner image is unavailable or changed'
require_original_bridge_namespace_absent || die 'the immutable 001 Owner bridge namespace appeared before Owner replacement'
require_prior_failed_runtime_ledger_absent || die 'the chained failed runtime evidence changed before Owner replacement'
require_failed_endpoint_phase_runtime || die 'the immutable 51e created-phase evidence changed before Owner replacement'
require_non_owner_inventory_unchanged || die 'an unrelated project service changed before Owner replacement'

owner_inventory="$(container_full_ids_for_service "$OWNER_SERVICE")" || die 'the Owner inventory could not be inspected'
if docker_local container inspect "$OLD_OWNER_CONTAINER_ID" >/dev/null 2>&1; then
  die 'the predecessor-removed historical Owner reappeared; this correction never stops or removes it'
fi
[[ -z "$(container_full_ids_for_service kemerbet-session-provision)" ]] || die 'the retired coordinator reappeared'
[[ -z "$(container_full_ids_for_volume "$PROFILE_VOLUME")" ]] || die 'the profile volume acquired a holder'
[[ "$owner_inventory" == "$CREATED_OWNER_CONTAINER_ID" ]] ||
  die 'the exact 51e-created Owner is not the sole Owner inventory'
[[ "$(container_full_ids_for_volume "$CONTROL_VOLUME")" == "$CREATED_OWNER_CONTAINER_ID" ]] ||
  die 'the exact 51e-created Owner is not the sole control-volume holder'
NEW_OWNER_CONTAINER_ID="$CREATED_OWNER_CONTAINER_ID"

require_prior_failed_recovery_claim ||
  die 'OWNER-DELTA-006: the immutable failed 1f27 bundle changed before replacement-record replay'
require_failed_network_scope_runtime ||
  die 'OWNER-DELTA-007: the immutable failed 1f27 intent-only runtime changed before replacement-record replay'
require_failed_owner_delta_runtime ||
  die 'OCI-RUNTIME-ID-006: the immutable failed a51 intent-only runtime changed before replacement-record replay'
require_failed_oci_identity_runtime ||
  die 'SEMANTIC-V2-006: the immutable failed 0ffc checkpoint changed before replacement-record replay'
if [[ -e "$BRIDGE_WORK_ROOT/replacement-owner-v1" && ! -L "$BRIDGE_WORK_ROOT/replacement-owner-v1" ]]; then
  load_replacement_record || die 'the replacement Owner record is invalid'
else
  publish_exact_record "$BRIDGE_WORK_ROOT/replacement-owner-v1" 0600 < <(emit_exact_nofollow_file \
    "$FAILED_RUNNING_STATUS_BRIDGE_REPLACEMENT" "$FAILED_RUNNING_STATUS_BRIDGE_REPLACEMENT_DEV_INO" \
    "$FAILED_RUNNING_STATUS_BRIDGE_REPLACEMENT_SIZE" "$FAILED_RUNNING_STATUS_BRIDGE_REPLACEMENT_SHA256") ||
    die 'the exact 8f replacement Owner identity could not be republished durably'
  load_replacement_record || die 'the published replacement Owner record is invalid'
fi
prepare_record_digests || die 'the replacement Owner digest is invalid'

require_owner_contract "$NEW_OWNER_CONTAINER_ID" "$CANONICAL_H14" "$SOURCE_OWNER_LOADED_IMAGE_ID" || die 'the recorded replacement Owner contract changed'
require_loaded_image_used_only_by "$NEW_OWNER_CONTAINER_ID" || die 'the recorded replacement is not the sole canonical-image user'
require_exact_owner_inventory "$NEW_OWNER_CONTAINER_ID" || die 'the replacement Owner inventory is not exactly one recorded container'
require_prior_failed_recovery_claim ||
  die 'OWNER-DELTA-008: the immutable failed 1f27 bundle changed before start-record replay'
require_failed_network_scope_runtime ||
  die 'OWNER-DELTA-009: the immutable failed 1f27 intent-only runtime changed before start-record replay'
require_failed_owner_delta_runtime ||
  die 'OCI-RUNTIME-ID-007: the immutable failed a51 intent-only runtime changed before start-record replay'
require_failed_oci_identity_runtime ||
  die 'SEMANTIC-V2-007: the immutable failed 0ffc checkpoint changed before start-record replay'
if [[ -e "$BRIDGE_WORK_ROOT/start-owner-v1" && ! -L "$BRIDGE_WORK_ROOT/start-owner-v1" ]]; then
  require_start_record || die 'the durable replacement start intent changed'
else
  publish_exact_record "$BRIDGE_WORK_ROOT/start-owner-v1" 0600 < <(emit_exact_nofollow_file \
    "$FAILED_RUNNING_STATUS_BRIDGE_START" "$FAILED_RUNNING_STATUS_BRIDGE_START_DEV_INO" \
    "$FAILED_RUNNING_STATUS_BRIDGE_START_SIZE" "$FAILED_RUNNING_STATUS_BRIDGE_START_SHA256") ||
    die 'the exact 8f start authorization could not be republished durably'
  require_start_record || die 'the published replacement start intent is invalid'
fi
prepare_record_digests || die 'the replacement start-intent digest is invalid'
require_complete_owner_endpoint_phase_boundary running ||
  die 'the complete running-phase boundary changed before completion publication'
publish_exact_record "$BRIDGE_WORK_ROOT/completed-v1" 0600 < <(expected_bridge_completed) ||
  die 'the Owner-runtime bridge completion could not be published durably'
require_bridge_completed || die 'the published Owner-runtime bridge completion is invalid'
[[ ! -e "$BRIDGE_ROOT" && ! -L "$BRIDGE_ROOT" ]] || die 'the final bridge namespace already exists unexpectedly'
require_exact_recovery_source_anchors || die 'an immutable 001 terminal or Owner bundle source anchor changed before ledger finalization'
require_original_bridge_namespace_absent || die 'the immutable 001 Owner bridge namespace appeared before ledger finalization'
require_prior_failed_runtime_ledger_absent || die 'the chained failed runtime evidence changed before ledger finalization'
require_financial_gates_disabled || die 'a financial, executor, provider, Amount, or Transfer gate changed before ledger finalization'
require_no_other_mutator_processes || die 'another staging mutation appeared before ledger finalization'
require_exact_droplet || die 'the staging Droplet identity changed before ledger finalization'
require_live_terminal_attestation_boundary "$NEW_OWNER_CONTAINER_ID" running ||
  die 'the terminal-attestation boundary changed before ledger finalization'
require_complete_owner_endpoint_phase_boundary running ||
  die 'the complete running-phase boundary changed before ledger finalization'
mv -- "$BRIDGE_INSTALLING" "$BRIDGE_ROOT" || die 'the bridge ledger could not be finalized'
sync -f "$BRIDGE_PARENT" || die 'the bridge ledger rename could not be synchronized'
BRIDGE_STATE='complete'
BRIDGE_WORK_ROOT="$BRIDGE_ROOT"
require_prior_failed_runtime_ledger_absent || die 'the immutable 911-absent and ff989-empty-pre-intent runtime evidence changed during finalization'
require_start_record || die 'the finalized Owner-runtime bridge start intent is invalid'
require_bridge_completed || die 'the finalized Owner-runtime bridge ledger is invalid'
require_customer_web_replacement_record || die 'the finalized customer-web replacement record is invalid'
require_owner_never_restarted || die 'Owner lifecycle changed before final immutable verification'
require_other_service_inventory_exact || die 'a non-customer service changed before final immutable verification'
require_failed_counter_runtime || die 'the immutable 020 empty pre-intent evidence changed during finalization'
require_prior_failed_recovery_claim ||
  die 'OWNER-DELTA-004: the immutable failed 1f27 bundle or manifest changed during finalization'
require_failed_customer_web_network_scope_runtime ||
  die 'CW-NET-SCOPE-005: the immutable failed 0110 empty pre-intent ledger changed during finalization'
require_failed_network_scope_runtime ||
  die 'OWNER-DELTA-005: the immutable failed 1f27 single-intent pre-mutation ledger changed during finalization'
require_failed_owner_delta_runtime ||
  die 'OCI-RUNTIME-ID-005: the immutable failed a51 intent-only runtime or descriptor residue changed during finalization'
require_failed_oci_identity_runtime ||
  die 'SEMANTIC-V2-005: the immutable failed 0ffc checkpoint or adopted healthy customer-web changed during finalization'
require_financial_gates_disabled || die 'a financial, executor, provider, Amount, or Transfer gate changed during finalization'

printf '%s\n' 'FetanAgent H14 customer-web recovery installed: Owner unchanged; customer-web only; all financial gates disabled; no provider action and no money moved.'
